-- [TSMod] npc_prohibit (generated by mods/npc_prohibit/make_mod.py): recruits whose characters this battle spawns as
-- NPCs are greyed out on the deploy screen, as vanilla does with AddProhibitedUnits. Silvio, Rufus, Jerrom
local tsmod_np_list = {"UNIT_MASTER_CH_N006", "UNIT_MASTER_CH_N007", "UNIT_MASTER_CH_N009"}
local tsmod_np_done = false
local tsmod_np_add = AddInitialPosition
function AddInitialPosition(...)
  if not tsmod_np_done then
    tsmod_np_done = true
    local ok, err = pcall(AddProhibitedUnits, tsmod_np_list)
    if TSLOG ~= nil then pcall(TSLOG, "npc_prohibit", ok, err, unpack(tsmod_np_list)) end
  end
  return tsmod_np_add(...)
end
